// Created by Patrik Sundblom — with OpenAI / ChatGPT as R&D support.
import {newProject,fingerprint} from './core/engine.mjs';
import {esc,tag,routeName,STATUS_LABELS,CONDITION_LABELS,pct} from './work-data.js';
export const EXAMPLES={
 portal:{title:'Kundportal',level:'Börja här · utan AI',story:'Kunder loggar in i samma webbportal för att läsa sina egna uppgifter. Varje konto ska hållas skilt från de andra.',goal:'Kan en inloggad kund läsa en annan kunds uppgifter?',assets:['Kunduppgifter','Konton','Inloggning'],focus:'F3',path:'Kund A → delad portal → kund B:s uppgifter',control:'Servern ska kontrollera att den inloggade kunden har rätt till just den post som efterfrågas.',bypass:'Vad händer om kund A ändrar postens ID i en direkt begäran, i stället för att använda portalens knappar?',test:'Använd två testkonton och en testpost. Försök läsa B:s post som A, både via gränssnittet och via postens direkta adress.',observation:'I det syntetiska exemplet nekas kund A åtkomst till B:s testpost. Den direkta begäran med B:s post-ID nekas också.',action:'Behåll testet med två konton och upprepa det för varje ingång som kan läsa kunduppgifter.',learn:'Ett angrepp kan vara möjligt enligt villkoren men ändå stoppas i ett test. Följ hur skyddet utmanas och hur resultatet dokumenteras.'},
 support:{title:'AI för kundsupport',level:'E-post och verktyg',story:'En AI läser kundmejl, söker i supportdokument och skriver ett svar. En person godkänner svaret innan ett verktyg skickar det.',goal:'Kan ett kundmejl styra AI:n att skicka information till fel mottagare?',assets:['Kunduppgifter','Supportdokument','Mottagaridentitet'],focus:'F1',path:'Kundmejl → AI:s utkast → sändverktyg',control:'Mottagare och sändbehörighet ska kontrolleras separat från texten som AI:n skriver.',bypass:'Kan en instruktion inne i kundmejlet ändra mottagare eller få ett annat innehåll skickat efter godkännandet?',test:'Lägg en ofarlig testinstruktion i ett testmejl. Kontrollera utkastet, den godkända mottagaren och sändverktygets faktiska anrop.',observation:'I det syntetiska exemplet påverkar testtexten utkastet, men mottagare och sändbehörighet förblir låsta. Hela angreppsvägen är därför fortfarande oavgjord.',action:'Behåll mottagarkontrollen utanför AI-utkastet och upprepa gränstestet när arbetsflödet ändras.',learn:'Skilj på att påverka ett utkast och att faktiskt kunna skicka fel meddelande. Ett delresultat avgör inte hela vägen.'},
 knowledge:{title:'Intern kunskapsassistent',level:'Dokument och behörighet',story:'Anställda frågar en läsande AI om interna dokument. Olika personer får läsa olika dokument. AI:n kan inte utföra åtgärder.',goal:'Kan en anställd få information ur ett dokument som personen saknar behörighet till?',assets:['Konfidentiella dokument','Användarbehörigheter'],focus:'F3',path:'Anställd A → dokumentsökning → skyddat dokument B',control:'Dokumentens åtkomstregler ska kontrolleras för den frågande användaren innan innehållet lämnas till AI:n.',bypass:'Går dokumentet att nå med en direkt referens även om det inte syns i sökresultatet?',test:'Pröva samma skyddade testdokument med två användare. Jämför både sökning och direkt uppslagning.',observation:'I det syntetiska exemplet nekas obehörig åtkomst både genom sökning och direkt uppslagning av testdokumentet.',action:'Behåll tester som jämför olika användares åtkomst till samma dokument.',learn:'Samma behörighetsgräns måste hålla genom både sökning och direkt åtkomst.'},
 invoice:{title:'Fakturahantering',level:'Lär dig vad ? betyder',story:'Ekonomiavdelningen laddar upp leverantörers PDF-fakturor. AI:n tar fram betalningsförslag. Det är ännu okänt om AI:n också söker i en intern kunskapskälla.',goal:'Kan en leverantörs dokument få extra tillit genom en okänd koppling till interna kunskapskällor?',assets:['Betalningsuppgifter','Leverantörsidentitet','Godkännanden'],focus:'F4',path:'Leverantörens PDF → eventuell kunskapskälla (?) → betalningsförslag',control:'Dokumentets ursprung och behörighet ska följa med genom varje kunskapskälla och in i betalningsförslaget.',bypass:'Kan leverantörstext behandlas som intern information efter att ha passerat en ansluten källa?',test:'Fastställ först om en intern kunskapskälla används. Om den används: följ ett ofarligt testinnehåll genom källa, svar och betalningsförslag.',observation:null,action:'Fastställ först om någon ansluten kunskapskälla används.',learn:'Det okända villkoret får stå kvar som ?. Vägen är villkorad och behöver mer underlag; den gissas inte bort.'},
 coding:{title:'Kod- och driftsättningsagent',level:'Befogenheter och åtgärder',story:'En AI-agent läser ärenden och paket, föreslår kod och kan driftsätta med ett tjänstekonto. Granskning krävs, men åtgärdens behörighetskontroll är ännu inte fastställd.',goal:'Kan agenten driftsätta något utanför den ändring som granskaren godkände?',assets:['Källkod','Driftsättningsnycklar','Produktion'],focus:'F2',path:'Ärendetext → agent → tjänstekonto → driftsättning',control:'Driftsättningsgränsen ska bara tillåta rätt kodarkiv, miljö och åtgärd för det aktuella godkännandet.',bypass:'Kan tjänstekontot utföra en annan driftsättning även när granskningen avser en begränsad ändring?',test:'Låt en testförfrågan begära en åtgärd utanför godkänt scope och kontrollera om driftsättningsgränsen nekar den.',observation:'I det syntetiska exemplet nekas testförfrågans driftsättning utanför godkänt scope, trots agentens rekommendation.',action:'Bind driftsättningsbehörigheten till godkänt kodarkiv, miljö och åtgärd.',learn:'En granskare och ett kraftfullt tjänstekonto räcker inte som förklaring. Pröva vad som faktiskt begränsar åtgärden.'}
};
export function loadExample(id){
 const g=EXAMPLES[id];if(!g)throw Error('Okänt exempel.');
 const p=newProject(id);Object.assign(p.input,{name:g.title,description:g.story,attackerGoal:g.goal,assets:[...g.assets]});
 const fp=fingerprint(p.input,p.excludedLenses);
 p.evidence=p.evidence.map(e=>({...e,source:'Syntetiskt genomarbetat exempel · '+g.title,observation:g.observation,fingerprint:fp}));
 for(const a of Object.values(p.actions))Object.assign(a,{owner:'Exempelansvarig',note:g.action,fingerprint:fp});
 return p;
}
export function exampleFor(p){return p.example?Object.values(EXAMPLES).find(g=>g.title===p.input.name):null;}
const steps=['Mål','Väg','Skydd','Motprövning','Belägg'];
const heading=(kicker,title,text)=>`<div class="page-heading"><div><div class="page-kicker">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(text)}</p></div></div>`;
export function examplesView(p){return heading('KOM IGÅNG','Välj ett exempel. Följ det hela vägen.','Ladda ett färdigt fall och gå igenom fem enkla frågor. Samma system följer med till resultatet och rapporten.')+`<div class="start-actions"><button class="secondary" data-view="guide">Fortsätt: ${esc(p.input.name)} →</button><button class="text-btn" data-scenario="custom">＋ Undersök mitt eget system</button></div><div class="example-cards">${Object.entries(EXAMPLES).map(([id,g])=>`<article class="worked-card ${id==='portal'?'recommended':''}"><div class="eyebrow">${esc(g.level)}</div><h2>${esc(g.title)}</h2><p>${esc(g.story)}</p><div class="example-question">${esc(g.goal)}</div><button class="${id==='portal'?'primary':'secondary'}" data-scenario="${id}">Ladda ${esc(g.title)} →</button><small>${g.observation?'Med tydligt märkta syntetiska observationer och åtgärd.':'Med okänt villkor och nästa fråga att reda ut.'}</small></article>`).join('')}</div><p class="help start-note">Exemplen fyller den riktiga undersökningen. Du kan ändra uppgifterna, pröva andra vägar och öppna rapporten. Varje laddning sparas som ett eget fall.</p>`;}
export function guideView(p,m,step,routeId){
 const g=exampleFor(p),r=m.routes.find(x=>x.id===routeId)||m.routes.find(x=>x.id===g?.focus)||m.routes[0];
 const same=g&&r?.id===g.focus, records=p.evidence.filter(e=>e.findingId===r?.id&&e.fingerprint===m.fingerprint);
 const selected=r?`<div class="selected-path"><span>VALD VÄG</span><strong>${esc(r.id)} · ${esc(routeName(r))}</strong><button class="text-btn" data-step="2">Byt väg</button></div>`:'';
 const stepper=`<nav class="investigation-steps" aria-label="Undersökningens fem steg">${steps.map((s,i)=>`<button data-step="${i+1}" ${step===i+1?'aria-current="step"':''}><b>${i+1}</b><span>${s}</span></button>`).join('')}</nav>`;
 const names=['Vad vill vi förhindra?','Hur skulle det kunna hända?','Vad ska stoppa det?','Hur prövar vi skyddet?','Vad visar underlaget?'];
 const captions=['Beskriv systemet och det oönskade utfallet.','Välj en väg att undersöka. Den följer med i nästa steg.','Formulera kontrollen som måste hålla för just den valda vägen.','Utmana kontrollen och välj ett test som kan säga emot hypotesen.','Samla observationer, bestäm nästa åtgärd och öppna rapporten.'];
 let body='';
 if(step===1)body=`<form id="guide-system-form" class="panel form-panel"><div class="field"><label for="g-goal">Det oönskade utfallet</label><textarea id="g-goal" name="attackerGoal" required maxlength="20000" placeholder="Exempel: En kund läser en annan kunds uppgifter.">${esc(p.input.attackerGoal)}</textarea></div><div class="guide-context"><strong>${esc(p.input.name)}</strong><p>${esc(p.input.description)||'Beskriv hur ditt system används.'}</p><p><b>Det vi skyddar:</b> ${p.input.assets.map(esc).join(', ')||'Inte angivet ännu'}</p></div><details ${p.example?'':'open'}><summary>Beskriv eller ändra systemet</summary><div class="field"><label for="g-name">Systemets namn</label><input id="g-name" name="name" required maxlength="160" value="${esc(p.input.name)}"></div><div class="field"><label for="g-description">Hur fungerar det?</label><textarea id="g-description" name="description" required maxlength="20000">${esc(p.input.description)}</textarea></div><div class="field"><label for="g-assets">Vad ska skyddas? Separera med komma</label><input id="g-assets" name="assets" maxlength="3000" value="${esc(p.input.assets.join(', '))}"></div></details><div class="guide-facts"><p><b>${m.unknown.length} okända villkor.</b> Ja (1), nej (0) och okänt (?) styr vilka vägar som är möjliga.</p><button type="button" class="secondary" data-view="system">Granska systemets villkor →</button></div></form>`;
 else if(!r)body=`<div class="panel form-panel"><h2>Ingen väg återstår med de här villkoren.</h2><p>Granska uppgifterna och de okända villkoren. Ett tomt resultat är inte en säkerhetsbedömning.</p><button class="primary" data-view="system">Granska villkoren →</button></div>`;
 else if(step===2)body=`<div class="guide-route-list">${m.routes.map(x=>`<button class="guide-route ${x.id===r.id?'selected':''}" data-choose-route="${x.id}" aria-pressed="${x.id===r.id}"><span class="route-id">${x.id}</span><div><strong>${esc(routeName(x))}</strong><p>${x.conditional?'Beror på ett okänt villkor':'Möjlig enligt systemets villkor'}${g?.focus===x.id?' · Exemplet följer denna väg':''}</p></div><span class="route-check">${x.id===r.id?'✓':'○'}</span></button>`).join('')}</div><section class="panel form-panel guide-explanation"><h2>Varför finns den valda vägen?</h2><p>${esc(same?g.path:r.path)}</p><p>${esc(same?g.learn:r.why)}</p>${r.missing.length?`<p class="unknown-note">Behöver klargöras: ${r.missing.map(k=>esc(CONDITION_LABELS[k]||k)).join(', ')}</p>`:''}<details><summary>Visa motorns villkor och resonemang</summary><p>${esc(r.why)}</p><button class="text-btn" data-route="${r.id}">Öppna detaljer →</button></details></section>`;
 else if(step===3)body=selected+`<section class="panel form-panel question-panel"><div class="eyebrow">SKYDDET ATT PRÖVA</div><p class="question-answer">${esc(same?g.control:r.control)}</p><div class="plain-explanation"><b>Oraklets fråga</b><p>Stoppar det här skyddet just den aktör, resurs och åtgärd som vägen beskriver?</p></div><p class="help">I nästa steg undersöker vi hur kontrollen skulle kunna fallera och vilket test som kan visa det.</p></section>`;
 else if(step===4)body=selected+`<section class="panel form-panel question-panel"><div class="eyebrow">UTMANA SKYDDET</div><p class="question-answer">${esc(same?g.bypass:r.bypass)}</p><div class="plain-explanation"><b>Ett konkret test</b><p>${esc(same?g.test:r.verify)}</p></div><p class="help">Om testet avslöjar en omväg: fråga igen vilket skydd som stoppar den. Det är den rekursiva prövningen.</p></section><details class="guide-advanced"><summary>Fördjupning: ändra villkor och följ Grover</summary><p>Prova ett uttryckligt scenario i det logiska rummet. Grover väljer automatiskt ett stopp; 40 är taket.</p><button class="secondary" data-action="guide-logic">Öppna den valda vägen i logiskt rum →</button></details>`;
 else body=selected+`<section class="panel form-panel"><h2>Underlaget för den här vägen</h2>${records.length?records.map(e=>`<article class="evidence-record">${tag(e.outcome==='refutes'?'Motsäger vägen':e.outcome==='supports'?'Stödjer vägen':'Oavgjort')}<p><strong>${esc(e.source)}</strong></p><p>${esc(e.observation)}</p></article>`).join(''):`<p class="no-evidence">${same&&g.focus==='F4'?'Ingen testobservation ännu. Fastställ först om den anslutna kunskapskällan används.':'Det finns inga observationer för den här vägen ännu. Kör testet och dokumentera vad som faktiskt hände.'}</p>`}<div class="plain-explanation"><b>Nästa steg</b><p>${esc(p.actions[r.id]?.fingerprint===m.fingerprint?p.actions[r.id].note:same?g.action:r.verify)}</p></div><details ${records.length?'':'open'}><summary>Lägg till en egen observation</summary><form id="evidence-form"><div class="field"><label for="g-source">Källa eller testreferens</label><input id="g-source" name="source" required maxlength="2000" placeholder="Test-ID, logg eller granskningsunderlag"></div><div class="field"><label for="g-observation">Förväntat och faktiskt resultat</label><textarea id="g-observation" name="observation" required maxlength="10000" placeholder="Vem försökte göra vad? Vad borde hända? Vad hände?"></textarea></div><div class="field"><label for="g-outcome">Vad säger observationen?</label><select id="g-outcome" name="outcome"><option value="inconclusive">Oavgjort</option><option value="supports">Stödjer vägen</option><option value="refutes">Motsäger vägen</option></select></div><button class="primary" type="submit">Spara observation</button></form></details><button class="text-btn" data-view="evidence">Hantera åtgärd och ansvarig →</button></section>`;
 return `<div class="guided-investigation">${stepper}${heading('STEG '+step+' AV 5',names[step-1],captions[step-1])}${p.example?`<div class="worked-banner"><b>Genomarbetat exempel · ${esc(p.input.name)}</b><span>Inbyggda observationer är syntetiska och visar hur arbetsflödet används.</span></div>`:''}${body}<div class="journey-navigation">${step>1?`<button class="secondary" data-step="${step-1}">← Tillbaka</button>`:`<button class="text-btn" data-view="examples">Byt exempel</button>`}${step<5?`<button class="primary" data-step="${step+1}">Nästa: ${steps[step]} →</button>`:`<button class="primary" data-action="report">Öppna rapporten →</button>`}</div></div>`;
}
export function resultsView(p,m){return heading('SAMMA UNDERSÖKNING','Det här har kommit fram.',p.input.name)+`<section class="panel form-panel"><h2>${esc(p.input.attackerGoal)||'Beskriv först det oönskade utfallet.'}</h2><p class="result-sentence">${m.routes.length} vägar återstår att bedöma. ${m.routes.filter(r=>r.conditional).length} beror på okända villkor.</p>${p.example?'<p class="help">Genomarbetat exempel: inbyggda observationer är syntetiska.</p>':''}</section><div class="result-paths">${m.routes.map(r=>`<article class="result-path"><div><span class="route-id">${r.id}</span><h2>${esc(routeName(r))}</h2>${tag(STATUS_LABELS[r.status]||r.status,r.conditional?'amber':'muted')}</div><p>${r.conditional?'Klargör först: '+r.missing.map(k=>esc(CONDITION_LABELS[k]||k)).join(', '):'Nästa steg: pröva skyddet och jämför med underlaget.'}</p><button class="text-btn" data-follow-route="${r.id}">Följ den här vägen →</button></article>`).join('')}</div><div class="form-actions"><button class="secondary" data-view="diagnostics">Visa tekniska analysdata</button><button class="primary" data-action="report">Öppna rapporten →</button></div>`;}
export function advancedView(){return heading('FÖRDJUPNING','Verktyg när du behöver dem.','Undersökningen och det laddade exemplet följer med.')+`<div class="example-cards">${[['system','System & villkor','Ändra systembeskrivningen, 1/0/? och de perspektiv som används.'],['logic','Logiskt rum & Grover','Pröva egna kontrollorakel, ändra dimensioner och följ automatisk förstärkning.'],['diagnostics','Tekniska analysdata','Se kandidatantal, orakelöversikt och kopplingar mellan angreppsmodeller.']].map(([id,t,d])=>`<article class="worked-card"><h2>${t}</h2><p>${d}</p><button class="secondary" data-view="${id}">Öppna →</button></article>`).join('')}</div><button class="text-btn" data-view="guide">← Tillbaka till undersökningen</button>`;}
export function stopExplanation(a){const n=a.alignment.evaluatedIterations??a.trace.at(-1)?.iteration??a.iterations;const reason=({all_states_accepted:'Alla tillstånd accepteras redan.',no_solutions:'Oraklet accepterar inga tillstånd.',threshold_reached:'Målet på 95 % nåddes.',gain_stalled:'Ingen tydlig förbättring under tre steg.',iteration_limit:'Iterationstaket nåddes.'})[a.alignment.reason]||'Sökningen är avslutad.';return `${reason} Sökningen prövade ${n} steg och behöll iteration ${a.iterations} (${pct(a.probability)}).`}
